/*!< USB  Endpoint-specific registers */
#define USB_EP0R                                            USB_BASE                                      /*!< USB Endpoint 0 register address */
#define USB_EP1R                                            (USB_BASE + 0x00000004)                       /*!< USB Endpoint 1 register address */
#define USB_EP2R                                            (USB_BASE + 0x00000008)                       /*!< USB Endpoint 2 register address */
#define USB_EP3R                                            (USB_BASE + 0x0000000C)                       /*!< USB Endpoint 3 register address */
#define USB_EP4R                                            (USB_BASE + 0x00000010)                       /*!< USB Endpoint 4 register address */
#define USB_EP5R                                            (USB_BASE + 0x00000014)                       /*!< USB Endpoint 5 register address */
#define USB_EP6R                                            (USB_BASE + 0x00000018)                       /*!< USB Endpoint 6 register address */
#define USB_EP7R                                            (USB_BASE + 0x0000001C)                       /*!< USB Endpoint 7 register address */


/* bit positions */
#define USB_EPADDR_FIELD_Pos                                (0U)
#define USB_EPADDR_FIELD_Msk                                (0xFUL << USB_EPADDR_FIELD_Pos)
#define USB_EPADDR_FIELD                                    USB_EPADDR_FIELD_Msk                          /*!< USB EndPoint ADDRess FIELD */
#define USB_EPTX_STAT_Pos                                   (4U)
#define USB_EPTX_STAT_Msk                                   (0x3UL << USB_EPTX_STAT_Pos)
#define USB_EPTX_STAT                                       USB_EPTX_STAT_Msk                             /*!< USB EndPoint TX STATus bit field */
#define USB_EP_DTOG_TX_Pos                                  (6U)
#define USB_EP_DTOG_TX_Msk                                  (0x1UL << USB_EP_DTOG_TX_Pos)
#define USB_EP_DTOG_TX                                      USB_EP_DTOG_TX_Msk                            /*!< USB EndPoint Data TOGGLE TX */
#define USB_EP_CTR_TX_Pos                                   (7U)
#define USB_EP_CTR_TX_Msk                                   (0x1UL << USB_EP_CTR_TX_Pos)
#define USB_EP_CTR_TX                                       USB_EP_CTR_TX_Msk                             /*!< USB EndPoint Correct TRansfer TX */
#define USB_EP_KIND_Pos                                     (8U)
#define USB_EP_KIND_Msk                                     (0x1UL << USB_EP_KIND_Pos)
#define USB_EP_KIND                                         USB_EP_KIND_Msk                               /*!< USB EndPoint KIND */
#define USB_EP_T_FIELD_Pos                                  (9U)
#define USB_EP_T_FIELD_Msk                                  (0x3UL << USB_EP_T_FIELD_Pos)
#define USB_EP_T_FIELD                                      USB_EP_T_FIELD_Msk                            /*!< USB EndPoint TYPE */
#define USB_EP_SETUP_Pos                                    (11U)
#define USB_EP_SETUP_Msk                                    (0x1UL << USB_EP_SETUP_Pos)
#define USB_EP_SETUP                                        USB_EP_SETUP_Msk                              /*!< USB EndPoint SETUP */
#define USB_EPRX_STAT_Pos                                   (12U)
#define USB_EPRX_STAT_Msk                                   (0x3UL << USB_EPRX_STAT_Pos)
#define USB_EPRX_STAT                                       USB_EPRX_STAT_Msk                             /*!< USB EndPoint RX STATus bit field */
#define USB_EP_DTOG_RX_Pos                                  (14U)
#define USB_EP_DTOG_RX_Msk                                  (0x1UL << USB_EP_DTOG_RX_Pos)
#define USB_EP_DTOG_RX                                      USB_EP_DTOG_RX_Msk                            /*!< USB EndPoint Data TOGGLE RX */
#define USB_EP_CTR_RX_Pos                                   (15U)
#define USB_EP_CTR_RX_Msk                                   (0x1UL << USB_EP_CTR_RX_Pos)
#define USB_EP_CTR_RX                                       USB_EP_CTR_RX_Msk                             /*!< USB EndPoint Correct TRansfer RX */


/* EndPoint REGister MASK (no toggle fields) */
#define USB_EPREG_MASK                                      (USB_EP_CTR_RX|USB_EP_SETUP|USB_EP_T_FIELD|USB_EP_KIND|USB_EP_CTR_TX|USB_EPADDR_FIELD)
                                                                                                          /*!< USB EP_TYPE[1:0] EndPoint TYPE */
#define USB_EP_TYPE_MASK_Pos                                (9U)
#define USB_EP_TYPE_MASK_Msk                                (0x3UL << USB_EP_TYPE_MASK_Pos)
#define USB_EP_TYPE_MASK                                    USB_EP_TYPE_MASK_Msk                          /*!< USB EndPoint TYPE Mask */
#define USB_EP_BULK                                         0x00000000U                                   /*!< USB EndPoint BULK */
#define USB_EP_CONTROL                                      0x00000200U                                   /*!< USB EndPoint CONTROL */
#define USB_EP_ISOCHRONOUS                                  0x00000400U                                   /*!< USB EndPoint ISOCHRONOUS */
#define USB_EP_INTERRUPT                                    0x00000600U                                   /*!< USB EndPoint INTERRUPT */
#define USB_EP_T_MASK                                       (~USB_EP_T_FIELD & USB_EPREG_MASK)


#define USB_EPKIND_MASK                                     (~USB_EP_KIND & USB_EPREG_MASK)               /*!< USB EP_KIND EndPoint KIND */
                                                                                                          /*!< USB STAT_TX[1:0] STATus for TX transfer */
#define USB_EP_TX_DIS                                       0x00000000U                                   /*!< USB EndPoint TX DISabled */
#define USB_EP_TX_STALL                                     0x00000010U                                   /*!< USB EndPoint TX STALLed */
#define USB_EP_TX_NAK                                       0x00000020U                                   /*!< USB EndPoint TX NAKed */
#define USB_EP_TX_VALID                                     0x00000030U                                   /*!< USB EndPoint TX VALID */
#define USB_EPTX_DTOG1                                      0x00000010U                                   /*!< USB EndPoint TX Data TOGgle bit1 */
#define USB_EPTX_DTOG2                                      0x00000020U                                   /*!< USB EndPoint TX Data TOGgle bit2 */
#define USB_EPTX_DTOGMASK                                   (USB_EPTX_STAT|USB_EPREG_MASK)
                                                                                                          /*!< USB STAT_RX[1:0] STATus for RX transfer */
#define USB_EP_RX_DIS                                       0x00000000U                                   /*!< USB EndPoint RX DISabled */
#define USB_EP_RX_STALL                                     0x00001000U                                   /*!< USB EndPoint RX STALLed */
#define USB_EP_RX_NAK                                       0x00002000U                                   /*!< USB EndPoint RX NAKed */
#define USB_EP_RX_VALID                                     0x00003000U                                   /*!< USB EndPoint RX VALID */
#define USB_EPRX_DTOG1                                      0x00001000U                                   /*!< USB EndPoint RX Data TOGgle bit1 */
#define USB_EPRX_DTOG2                                      0x00002000U                                   /*!< USB EndPoint RX Data TOGgle bit1 */
#define USB_EPRX_DTOGMASK                                   (USB_EPRX_STAT|USB_EPREG_MASK)


