#define USB_EP0R_DTOG_RX                                    USB_EP0R_DTOG_RX_Msk                          /*!< USB Data Toggle, for reception transfers */
#define USB_EP0R_CTR_RX_Pos                                 (15U)
#define USB_EP0R_CTR_RX_Msk                                 (0x1UL << USB_EP0R_CTR_RX_Pos)
#define USB_EP0R_CTR_RX                                     USB_EP0R_CTR_RX_Msk                           /*!< USB Correct Transfer for reception */


