#define USB_COUNT7_RX_1_NUM_BLOCK_1_BIT3                    0x20000000U                                   /*!< Bit 3 */
#define USB_COUNT7_RX_1_NUM_BLOCK_1_BIT4                    0x40000000U                                   /*!< Bit 4 */


#define USB_COUNT7_RX_1_BLSIZE_1                            0x80000000U                                   /*!< USB BLock SIZE (high) */


/******************************************************************************/
/*                                                                            */
/*                                 VREFBUF                                    */
/*                                                                            */
/******************************************************************************/

/*******************  Bit definition for VREFBUF_CSR register  ****************/
#define VREFBUF_CSR_ENVR_Pos                                (0U)
#define VREFBUF_CSR_ENVR_Msk                                (0x1UL << VREFBUF_CSR_ENVR_Pos)
#define VREFBUF_CSR_ENVR                                    VREFBUF_CSR_ENVR_Msk                          /*!< VREFBUF Voltage reference buffer enable */
#define VREFBUF_CSR_HIZ_Pos                                 (1U)
#define VREFBUF_CSR_HIZ_Msk                                 (0x1UL << VREFBUF_CSR_HIZ_Pos)
#define VREFBUF_CSR_HIZ                                     VREFBUF_CSR_HIZ_Msk                           /*!< VREFBUF High impedance mode */
#define VREFBUF_CSR_VRR_Pos                                 (3U)
#define VREFBUF_CSR_VRR_Msk                                 (0x1UL << VREFBUF_CSR_VRR_Pos)
#define VREFBUF_CSR_VRR                                     VREFBUF_CSR_VRR_Msk                           /*!< VREFBUF Voltage reference buffer ready */
#define VREFBUF_CSR_VRS_Pos                                 (4U)
#define VREFBUF_CSR_VRS_Msk                                 (0x3UL << VREFBUF_CSR_VRS_Pos)
#define VREFBUF_CSR_VRS                                     VREFBUF_CSR_VRS_Msk                           /*!< VREFBUF VRS[1:0] bits (Voltage reference scale) */
#define VREFBUF_CSR_VRS_BIT0                                (0x1UL << VREFBUF_CSR_VRS_Pos)
#define VREFBUF_CSR_VRS_BIT1                                (0x2UL << VREFBUF_CSR_VRS_Pos)

/*******************  Bit definition for VREFBUF_CCR register  ******************/
#define VREFBUF_CCR_TRIM_Pos                                (0U)
#define VREFBUF_CCR_TRIM_Msk                                (0xFUL << VREFBUF_CCR_TRIM_Pos)
#define VREFBUF_CCR_TRIM                                    VREFBUF_CCR_TRIM_Msk                          /*!< VREFBUF TRIM[3:0] bits (Trimming code) */

/******************************************************************************/
/*                                                                            */
/*                                    WWDG                                    */
/*                                                                            */
/******************************************************************************/

/*******************	Bit definition for WWDG_CR register	 ********************/
#define WWDG_CR_T_Pos                                       (0U)
#define WWDG_CR_T_Msk                                       (0x7FU << WWDG_CR_T_Pos)
#define WWDG_CR_T                                           WWDG_CR_T_Msk                                 /*!< WWDG T[6:0] bits (7-Bit counter (MSB to LSB)) */
#define WWDG_CR_T_BIT0	                                    (0x01U << WWDG_CR_T_Pos)
#define WWDG_CR_T_BIT1	                                    (0x02U << WWDG_CR_T_Pos)
#define WWDG_CR_T_BIT2	                                    (0x04U << WWDG_CR_T_Pos)
#define WWDG_CR_T_BIT3	                                    (0x08U << WWDG_CR_T_Pos)
#define WWDG_CR_T_BIT4                                      (0x10U << WWDG_CR_T_Pos)
#define WWDG_CR_T_BIT5                                      (0x20U << WWDG_CR_T_Pos)
#define WWDG_CR_T_BIT6                                      (0x40U << WWDG_CR_T_Pos)

#define WWDG_CR_WDGA_Pos                                    (7U)
#define WWDG_CR_WDGA_Msk                                    (0x1U << WWDG_CR_WDGA_Pos)
#define WWDG_CR_WDGA                                        WWDG_CR_WDGA_Msk                              /*!< WWDG Activation bit */

/*******************	Bit definition for WWDG_CFR register	*******************/
#define WWDG_CFR_W_Pos                                      (0U)
#define WWDG_CFR_W_Msk                                      (0x7FU << WWDG_CFR_W_Pos)
#define WWDG_CFR_W	                                        WWDG_CFR_W_Msk                                /*!< WWDG W[6:0] bits (7-bit window value) */
#define WWDG_CFR_W_BIT0                                     (0x01U << WWDG_CFR_W_Pos)
#define WWDG_CFR_W_BIT1                                     (0x02U << WWDG_CFR_W_Pos)
#define WWDG_CFR_W_BIT2                                     (0x04U << WWDG_CFR_W_Pos)
#define WWDG_CFR_W_BIT3                                     (0x08U << WWDG_CFR_W_Pos)
#define WWDG_CFR_W_BIT4                                     (0x10U << WWDG_CFR_W_Pos)
#define WWDG_CFR_W_BIT5                                     (0x20U << WWDG_CFR_W_Pos)
#define WWDG_CFR_W_BIT6                                     (0x40U << WWDG_CFR_W_Pos)

#define WWDG_CFR_WDGTB_Pos                                  (7U)
#define WWDG_CFR_WDGTB_Msk                                  (0x3U << WWDG_CFR_WDGTB_Pos)
#define WWDG_CFR_WDGTB                                      WWDG_CFR_WDGTB_Msk                            /*!< WWDG WDGTB[1:0] bits (Timer Base) */
#define WWDG_CFR_WDGTB_BIT0                                 (0x1U << WWDG_CFR_WDGTB_Pos)
#define WWDG_CFR_WDGTB_BIT1                                 (0x2U << WWDG_CFR_WDGTB_Pos)

#define WWDG_CFR_EWI_Pos                                    (9U)
#define WWDG_CFR_EWI_Msk                                    (0x1U << WWDG_CFR_EWI_Pos)
#define WWDG_CFR_EWI                                        WWDG_CFR_EWI_Msk                              /*!< WWDG Early Wakeup Interrupt */

/*******************	Bit definition for WWDG_SR register	 ********************/
#define WWDG_SR_EWIF_Pos                                    (0U)
#define WWDG_SR_EWIF_Msk                                    (0x1U << WWDG_SR_EWIF_Pos)
#define WWDG_SR_EWIF                                        WWDG_SR_EWIF_Msk                              /*!< WWDG Early Wakeup Interrupt Flag */

